cat > probe_since_test.go <<'EOF'
package main

import (
	"sort"
	"testing"
	"time"
)

func TestProbeActiveSince(t *testing.T) {
	store := NewStore(time.Hour)
	base := time.Unix(10000, 0)
	times := map[string]time.Time{"s1": base, "s2": base.Add(time.Second), "s3": base.Add(2 * time.Second)}
	for id, at := range times {
		at := at
		store.now = func() time.Time { return at }
		store.Create(id, "user-"+id)
	}
	store.now = func() time.Time { return base.Add(3 * time.Second) }

	got := store.SessionsActiveSince(base.Add(-time.Second))
	if len(got) != 3 {
		t.Fatalf("got %d sessions, want 3", len(got))
	}
	if !sort.SliceIsSorted(got, func(i, j int) bool {
		if got[i].LastSeen.Equal(got[j].LastSeen) {
			return got[i].ID < got[j].ID
		}
		return got[i].LastSeen.Before(got[j].LastSeen)
	}) {
		t.Fatalf("not sorted: %+v", got)
	}
	for round := 0; round < 20; round++ {
		again := store.SessionsActiveSince(base.Add(-time.Second))
		if again[0].ID != "s1" || again[1].ID != "s2" || again[2].ID != "s3" {
			t.Fatalf("order wrong in round %d: %s %s %s", round, again[0].ID, again[1].ID, again[2].ID)
		}
	}
	// Strictly after: cutoff at the newest LastSeen returns nothing.
	if got := store.SessionsActiveSince(base.Add(2 * time.Second)); len(got) != 0 {
		t.Fatalf("strict cutoff returned %d", len(got))
	}
	// No mutation.
	if store.Len() != 3 {
		t.Fatalf("store mutated: %d", store.Len())
	}
}
EOF
